import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const AREAS = ['예산', '회계', '인사'];
const LOGIN_TYPES = ['웹', '메신저', '모바일'];
// 가정: 개인정보 열람 로그의 열람 대상 정보 유형 (코드 목록 미확정)
const HR_TARGET_INFO_TYPE = '인사정보';
// 가정: 접속 채널은 x-login-type 헤더로 받고, 없거나 허용값이 아니면 웹으로 본다
const DEFAULT_LOGIN_TYPE = '웹';
// 가정: 클라이언트 IP를 알 수 없을 때 쓰는 값
const UNKNOWN_IP = '0.0.0.0';

function detectArea(question: string): string | null {
  if (/예산|본예산|실행예산/.test(question)) {
    return '예산';
  }
  if (/회계|전표|결의|차변|대변/.test(question)) {
    return '회계';
  }
  if (/인사|직원|임직원|재직|퇴직|급여/.test(question)) {
    return '인사';
  }
  return null;
}

function won(value: unknown): string {
  return Number(value).toLocaleString('ko-KR');
}

@Controller('api/v1')
export class FnSfr04403Controller {
  @Post('/ai-analysis-queries')
  @HttpCode(200)
  async createAiAnalysisQuery(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const rawQuestion = data['question'];
    if (rawQuestion === undefined || rawQuestion === null || typeof rawQuestion !== 'string') {
      throw new ApiError(400, 'VALIDATION_FAILED', '질문을 입력해 주세요.');
    }
    const question = rawQuestion.trim();
    if (question === '') {
      throw new ApiError(422, 'AI_QUERY_UNINTERPRETABLE', '질의 내용이 비어 있어 해석할 수 없습니다.');
    }
    const rawArea = data['targetArea'];
    let area: string | null = null;
    if (rawArea !== undefined && rawArea !== null && rawArea !== '') {
      if (typeof rawArea !== 'string' || !AREAS.includes(rawArea)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '분석 대상 영역은 예산, 회계, 인사 중 하나여야 합니다.');
      }
      area = rawArea;
    } else {
      area = detectArea(question);
    }
    if (area === null) {
      throw new ApiError(422, 'AI_QUERY_UNINTERPRETABLE', '질의에서 예산·회계·인사 중 분석 대상 영역을 알 수 없습니다.');
    }
    const targetArea: string = area;
    const headerType = req.headers['x-login-type'];
    const loginType = typeof headerType === 'string' && LOGIN_TYPES.includes(headerType) ? headerType : DEFAULT_LOGIN_TYPE;
    const loginIp = (req.ip || UNKNOWN_IP).slice(0, 45);

    return transaction(async (db) => {
      let analysisResult = '';
      let answer = '';
      try {
        if (targetArea === '예산') {
          const main = await db.query(
            'SELECT COUNT(*) AS "cnt", COALESCE(SUM(request_amount), 0) AS "total" FROM main_budget',
            {},
          );
          const exec = await db.query(
            'SELECT COUNT(*) AS "cnt", COALESCE(SUM(amount), 0) AS "total" FROM exec_budget',
            {},
          );
          analysisResult = '본예산 ' + won(main[0]['cnt']) + '건(신청금액 합계 ' + won(main[0]['total']) + '원), 실행예산 ' + won(exec[0]['cnt']) + '건(금액 합계 ' + won(exec[0]['total']) + '원)입니다.';
          answer = '질문하신 예산 현황은 ' + analysisResult;
        } else if (targetArea === '회계') {
          const jv = await db.query(
            'SELECT COUNT(*) AS "cnt", COALESCE(SUM(debit_total), 0) AS "debit", COALESCE(SUM(credit_total), 0) AS "credit" FROM journal_voucher',
            {},
          );
          analysisResult = '전표 ' + won(jv[0]['cnt']) + '건, 차변 합계 ' + won(jv[0]['debit']) + '원, 대변 합계 ' + won(jv[0]['credit']) + '원입니다.';
          answer = '질문하신 회계 현황은 ' + analysisResult;
        } else {
          const hr = await db.query(
            'SELECT employment_status AS "status", COUNT(*) AS "cnt" FROM hr_record GROUP BY employment_status ORDER BY employment_status',
            {},
          );
          const parts = hr.map((row: Record<string, unknown>) => String(row['status']) + ' ' + won(row['cnt']) + '명');
          analysisResult = parts.length > 0 ? '재직 구분별 인원은 ' + parts.join(', ') + '입니다.' : '조회된 인사정보가 없습니다.';
          answer = '질문하신 인사 현황은 ' + analysisResult;
        }
      } catch (e) {
        if (e instanceof ApiError) {
          throw e;
        }
        throw new ApiError(502, 'AI_ANALYSIS_FAILED', 'AI 분석에 실패했습니다. 잠시 후 다시 시도해 주세요.');
      }

      if (targetArea === '인사') {
        await db.execute(
          'INSERT INTO access_log (employee_id, event_type, accessed_at, login_ip, login_type, target_info_type, created_at, updated_at) ' +
            'VALUES (CAST(:userId AS bigint), :eventType, now(), :loginIp, :loginType, :targetInfoType, now(), now())',
          {
            userId: user.id,
            eventType: '개인정보열람',
            loginIp,
            loginType,
            targetInfoType: HR_TARGET_INFO_TYPE,
          },
        );
      }

      return { analysisResult, answer };
    });
  }
}

