import { useState } from 'react';
import type { PageProps, Row } from '../kit';
import { call, Band, DataTable, Drawer, Form, Field, TextInput, Select, Pairs, Tiles, DateText } from '../kit';

const AREA_OPTIONS: [string, string][] = [
  ['예산', '예산'],
  ['회계', '회계'],
  ['인사', '인사'],
];

export default function FnSfr04403Page({ role, notify }: PageProps) {
  const [history, setHistory] = useState<Row[]>([]);
  const [asking, setAsking] = useState(false);
  const [detail, setDetail] = useState<Row | null>(null);
  const [question, setQuestion] = useState('');
  const [targetArea, setTargetArea] = useState('');

  function openAsk() {
    setQuestion('');
    setTargetArea('');
    setAsking(true);
  }

  async function submit() {
    if (question.trim() === '') {
      throw new Error('질문을 입력해 주세요.');
    }
    const body: Row = { question: question.trim() };
    if (targetArea !== '') {
      body.targetArea = targetArea;
    }
    const result = await call('POST', '/ai-analysis-queries', role, body);
    const row: Row = {
      id: history.length + 1,
      question: question.trim(),
      targetArea: targetArea,
      analysisResult: result.analysisResult,
      answer: result.answer,
      askedAt: new Date().toISOString(),
    };
    setHistory([row, ...history]);
    setAsking(false);
    setDetail(row);
    notify('질의 분석을 완료했습니다.');
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>이번 질의</h2>
        <Tiles items={[['이 화면에서 처리한 질의', history.length]]} />
      </section>
      <section className="box span-12">
        <h2>질의 내역</h2>
        <Band total={history.length}>
          <button type="button" onClick={openAsk}>질문하기</button>
        </Band>
        <DataTable
          columns={[
            { key: 'askedAt', label: '질의 시각', render: (r) => <DateText value={r.askedAt} time /> },
            { key: 'targetArea', label: '분석 대상 영역', render: (r) => <span>{String(r.targetArea || '자동 판별')}</span> },
            { key: 'question', label: '예산·회계·인사 데이터에 대한 질문' },
            { key: 'answer', label: '질의에 대한 AI 응답' },
          ]}
          rows={history}
          onRowClick={(r) => setDetail(r)}
          empty="아직 질의한 내역이 없습니다. 질문하기를 눌러 시작하세요."
        />
      </section>
      {asking && (
        <Drawer title="AI 분석 질문" onClose={() => setAsking(false)}>
          <Form onSubmit={submit} submit="분석 요청">
            <Field label="예산·회계·인사 데이터에 대한 질문" required wide>
              <TextInput value={question} onChange={setQuestion} multiline placeholder="예: 올해 본예산 신청금액 합계는?" />
            </Field>
            <Field label="분석 대상 영역(예산/회계/인사)" hint="비우면 질문 내용으로 자동 판별합니다.">
              <Select value={targetArea} onChange={setTargetArea} options={AREA_OPTIONS} placeholder="자동 판별" />
            </Field>
          </Form>
        </Drawer>
      )}
      {detail && (
        <Drawer title="질의 결과" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['질문', String(detail.question)],
              ['분석 대상 영역', String(detail.targetArea || '자동 판별')],
              ['데이터 분석 결과', String(detail.analysisResult)],
              ['질의에 대한 AI 응답', String(detail.answer)],
              ['질의 시각', <DateText value={detail.askedAt} time />],
            ]}
          />
        </Drawer>
      )}
    </div>
  );
}
